-- Generated by model/lib/sql/generate.mjs. Loads IMPORT FX Rate from cells/IMPORT FX Rate.csv in the folder of input cells. Two rows for one cell add up.
INSERT OR REPLACE INTO "IMPORT FX Rate" SELECT coalesce(k0."Currency", error('cells name a member Currency does not have: ' || c."Currency")), coalesce(k1."Years", error('cells name a member Years does not have: ' || c."Years")), coalesce(k2."Months", error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE)
FROM read_csv('cells/IMPORT FX Rate.csv', header = true, all_varchar = true) c LEFT JOIN "dim Currency" k0 ON k0.name = c."Currency" LEFT JOIN "dim Years" k1 ON k1.name = c."Years" LEFT JOIN "dim Months" k2 ON k2.name = c."Months"
GROUP BY ALL;
